  /// payloads zeroed while preserving their vectors and offsets.
  const ::flatbuffers::Vector<uint8_t> *SIGNATURE() const {
    return GetPointer<const ::flatbuffers::Vector<uint8_t> *>(VT_SIGNATURE);
  }
