  /// with both signature fields omitted.
  const ::flatbuffers::Vector<uint8_t> *CANONICAL_JSON_SIGNATURE() const {
    return GetPointer<const ::flatbuffers::Vector<uint8_t> *>(VT_CANONICAL_JSON_SIGNATURE);
  }
