           VerifyOffsetRequired(verifier, VT_SIGNATURE) &&
           verifier.VerifyVector(SIGNATURE()) &&
           VerifyOffsetRequired(verifier, VT_CANONICAL_JSON_SIGNATURE) &&
           verifier.VerifyVector(CANONICAL_JSON_SIGNATURE()) &&
           verifier.EndTable();
